const DESCRIPTIONS = {"@Créatures":["Fait apparaître cette créature au bloc visé.","Spawns this creature at the aimed block."],"@Lieux":["Te téléporte à la structure de ce type la plus proche, si elle existe dans cette dimension.","Teleports you to the nearest structure of this type, if it exists in this dimension."],"@Biomes":["Te téléporte à ce biome, s'il se trouve à moins de 6 400 blocs.","Teleports you to this biome if it is within 6,400 blocks."],"@Objets":["Ajoute ces objets à ton inventaire.","Adds these items to your inventory."],"Joueur":["Tout ce qui touche ton personnage : vie, déplacements, taille et capacités.","Everything about your character: health, movement, size and abilities."],"Téléportation":["Déplace-toi instantanément : bloc visé, structures, biomes, dimensions et radar à minerais.","Move instantly: aimed block, structures, biomes, dimensions and ore radar."],"Objets":["Récupère des objets, des armes divines et modifie l'objet que tu tiens.","Get items and divine weapons, and change the item you are holding."],"Créatures":["Fais apparaître des créatures, des montures et des gardes du corps.","Spawn creatures, mounts and bodyguards."],"Monde":["Contrôle l'heure, la météo, les règles du jeu et la difficulté.","Control the time, weather, game rules and difficulty."],"Pouvoirs":["Choisis le pouvoir utilisé par la touche R.","Pick the power fired by the R key."],"Chaos":["Pluies, contrôle du temps, bombe nucléaire et catastrophes.","Rains, time control, the nuke and disasters."],"Catastrophes":["Tornade, séisme, volcan et météorite. Le terrain change pour de bon.","Tornado, earthquake, volcano and meteorite. The land changes for good."],"Construction":["Pose des bâtiments complets en un appui, avec annulation.","Place complete buildings in one press, with undo."],"Structures":["Capture, importe, prévisualise et partage des structures, ou suis un plan en survie.","Capture, import, preview and share structures, or follow a plan in survival."],"Réglages":["Langue, thème, bannière, affichage, zoom et profils.","Language, theme, banner, display, zoom and profiles."],"Lieux":["Liste de structures vers lesquelles te téléporter.","A list of structures to teleport to."],"Biomes":["Liste de biomes vers lesquels te téléporter.","A list of biomes to teleport to."],"Tout désactiver":["Coupe tous les cheats actifs d'un coup.","Turns off every active cheat at once."],"Invincible":["Tu ne prends plus de dégâts et ta vie reste pleine. Le vide et /kill restent mortels.","You take no damage and stay at full health. The void and /kill can still kill you."],"Vol":["Tu peux voler comme en créatif : appuie deux fois sur saut.","Lets you fly as in creative: press jump twice."],"Faim infinie":["Ta barre de faim reste toujours pleine.","Your hunger bar always stays full."],"Air infini":["Tu ne te noies plus sous l'eau.","You no longer drown underwater."],"Vision nocturne":["Tu vois clair dans le noir, partout.","You can see clearly in the dark, everywhere."],"Minage rapide":["Tu casses les blocs beaucoup plus vite.","You break blocks much faster."],"Coup fatal":["Chaque coup tue presque tout d'un seul coup.","Each hit kills almost anything in one blow."],"Vitesse":["Multiplie ta vitesse de déplacement.","Multiplies your movement speed."],"Vitesse de vol":["Multiplie ta vitesse quand tu voles.","Multiplies your speed while flying."],"Saut":["Multiplie la hauteur de tes sauts.","Multiplies your jump height."],"Taille":["Change la taille de ton personnage, de minuscule à géant.","Changes the size of your character, from tiny to giant."],"Hauteur de marche":["Monte des blocs en marchant, sans sauter.","Walk up blocks without jumping."],"Portée":["Augmente la distance à laquelle tu touches les blocs et les créatures.","Increases how far you can reach blocks and creatures."],"Mode de jeu":["Passe en survie, créatif, aventure ou spectateur.","Switch to survival, creative, adventure or spectator."],"Soigner":["Remet ta vie au maximum et éteint le feu.","Restores your health and puts out any fire."],"Nourrir":["Remplit ta barre de faim.","Fills your hunger bar."],"Retirer les effets":["Enlève tous tes effets de potion.","Removes all your potion effects."],"+10 niveaux d'XP":["Te donne 10 niveaux d'expérience.","Gives you 10 experience levels."],"Réparer l'inventaire":["Répare tous les objets abîmés de ton inventaire.","Repairs every damaged item in your inventory."],"Jetpack (maintenir saut)":["Maintiens saut pour t'élever dans les airs. Les chutes ne te blessent plus.","Hold jump to rise into the air. Falls no longer hurt you."],"Invisible":["Ton personnage devient invisible.","Your character becomes invisible."],"Ignoré des monstres":["Les créatures proches arrêtent de te cibler.","Nearby creatures stop targeting you."],"Aimant à objets":["Attire les objets et l'expérience à moins de 32 blocs.","Pulls items and experience from up to 32 blocks away."],"Aura de mort":["Tue les monstres à moins de 10 blocs de toi.","Kills monsters within 10 blocks of you."],"Pont automatique":["Pose du verre sous tes pieds quand tu marches dans le vide. Sneak pour descendre.","Places glass under your feet as you walk over empty space. Sneak to go down."],"Mineur de filon":["Casser un minerai ou une bûche casse aussi les blocs reliés, jusqu'à 96.","Breaking an ore or log also breaks the connected blocks, up to 96."],"Gravité":["Change la force de la gravité sur ton personnage.","Changes how strongly gravity pulls your character."],"Recul des coups":["Tes coups projettent les créatures plus loin.","Your hits knock creatures back further."],"Sauts infinis":["Tu peux sauter de nouveau en plein air, sans limite.","You can jump again in mid-air, with no limit."],"Marche sur l'eau":["L'eau gèle sous tes pas, le temps de passer.","Water freezes under your feet as you walk."],"Main verte":["Fait pousser les plantes à moins de 6 blocs de toi.","Makes plants grow within 6 blocks of you."],"Réparation automatique":["Répare ton inventaire chaque seconde.","Repairs your inventory every second."],"Au bloc visé":["Te téléporte sur le bloc que tu regardes, jusqu'à 200 blocs.","Teleports you onto the block you are looking at, up to 200 blocks away."],"À la surface":["Te remonte à la surface, au-dessus de toi. Impossible dans le Nether.","Takes you up to the surface above you. Not possible in the Nether."],"Emplacement":["Choisis l'un des 5 emplacements de position de ce monde.","Pick one of this world's 5 position slots."],"Enregistrer la position":["Garde ta position dans l'emplacement choisi, même après avoir quitté le jeu.","Saves your position in the chosen slot, even after you quit the game."],"Retour à la position":["Te ramène à la position de l'emplacement choisi.","Takes you back to the position in the chosen slot."],"Village le plus proche":["Te téléporte au village le plus proche.","Teleports you to the nearest village."],"Fort le plus proche":["Te téléporte au fort le plus proche, celui du portail de l'End.","Teleports you to the nearest stronghold, home of the End portal."],"Overworld":["Te téléporte dans le monde normal, près du centre.","Teleports you to the normal world, near its center."],"Nether":["Te téléporte dans le Nether, sur un sol solide.","Teleports you to the Nether, on solid ground."],"End":["Te téléporte dans l'End, près de l'île centrale.","Teleports you to the End, near the main island."],"Retour au lieu de mort":["Te ramène là où tu es mort pour la dernière fois.","Takes you back to where you last died."],"Radar : minerai":["Choisis le minerai recherché par le radar.","Pick the ore the radar looks for."],"Radar : scanner":["Cherche le minerai le plus proche : 40 blocs autour de toi, 80 en hauteur.","Finds the nearest ore: 40 blocks around you, 80 up and down."],"Radar : y aller":["Te téléporte juste au-dessus du minerai trouvé, en creusant un passage.","Teleports you just above the ore it finds, digging out a space."],"Lieu au hasard":["Te téléporte à un endroit au hasard, entre 500 et 5 000 blocs.","Teleports you to a random place, 500 to 5,000 blocks away."],"Kit netherite complet":["Armure et outils en netherite, enchantés.","Enchanted netherite armor and tools."],"Épée divine":["Épée incassable : tranchant 255, butin 10, aura de feu 5.","Unbreakable sword: sharpness 255, looting 10, fire aspect 5."],"Pioche divine":["Pioche incassable : efficacité 255 et fortune 10.","Unbreakable pickaxe: efficiency 255 and fortune 10."],"Arc divin":["Arc incassable : puissance 255, flamme, infinité et frappe 10.","Unbreakable bow: power 255, flame, infinity and punch 10."],"Trident divin":["Trident incassable : empalement 255, loyauté et canalisation.","Unbreakable trident: impaling 255, loyalty and channeling."],"En main : enchanter au max":["Ajoute tous les enchantements possibles à l'objet en main, au niveau normal maximum.","Adds every possible enchantment to the held item, at its normal maximum level."],"En main : niveau 255":["Ajoute tous les enchantements possibles à l'objet en main, au niveau 255.","Adds every possible enchantment to the held item, at level 255."],"En main : incassable":["L'objet en main ne s'use plus jamais.","The held item never wears out again."],"En main : remplir la pile":["Remplit la pile de l'objet en main.","Fills the stack of the held item."],"En main : dupliquer":["Ajoute une copie de l'objet en main à ton inventaire.","Adds a copy of the held item to your inventory."],"Coffre de l'Ender portable":["Ouvre ton coffre de l'Ender, où que tu sois.","Opens your Ender chest, wherever you are."],"Cheval turbo":["Fait apparaître un cheval sellé, très rapide, et te met dessus.","Spawns a very fast saddled horse and puts you on it."],"Gardes du corps":["Fait apparaître 4 loups apprivoisés et 2 golems de fer à côté de toi.","Spawns 4 tamed wolves and 2 iron golems next to you."],"Chevaucher la créature visée":["Monte sur la créature que tu regardes, jusqu'à 40 blocs.","Climbs onto the creature you are looking at, up to 40 blocks away."],"Heure : matin":["Passe au matin.","Sets the time to morning."],"Heure : midi":["Passe à midi.","Sets the time to noon."],"Heure : nuit":["Passe à la nuit.","Sets the time to night."],"Figer l'heure":["Arrête le cycle du jour et de la nuit.","Stops the day and night cycle."],"Météo : dégagée":["Fait disparaître la pluie.","Clears the weather."],"Météo : pluie":["Fait tomber la pluie.","Starts the rain."],"Météo : orage":["Déclenche un orage.","Starts a thunderstorm."],"Figer la météo":["La météo actuelle ne change plus.","The current weather stops changing."],"Garder l'inventaire":["Tu gardes tes objets quand tu meurs.","You keep your items when you die."],"Apparition des monstres":["Autorise ou bloque l'apparition naturelle des créatures.","Allows or blocks natural creature spawning."],"Retirer les monstres":["Supprime tous les monstres chargés, sauf le dragon de l'Ender.","Removes all loaded monsters, except the Ender dragon."],"Éclair au bloc visé":["Fait tomber un éclair sur le bloc que tu regardes.","Strikes lightning on the block you are looking at."],"TNT au bloc visé":["Pose une TNT allumée sur le bloc que tu regardes.","Places lit TNT on the block you are looking at."],"Difficulté":["Change la difficulté du monde.","Changes the world's difficulty."],"Pouvoir (touche R)":["Choisis ton pouvoir, puis utilise-le avec R. Maintiens R pour tirer en rafale.","Pick your power, then use it with R. Hold R to keep firing."],"Flèches explosives":["Tes flèches explosent à l'impact.","Your arrows explode on impact."],"Pluie":["Fait tomber des météores, des TNT, des enclumes et plus encore autour de toi.","Rains meteors, TNT, anvils and more around you."],"Vitesse du temps":["Ralentit ou accélère tout le jeu.","Slows down or speeds up the whole game."],"Arrêt du temps":["Fige le monde. Toi seul peux encore bouger.","Freezes the world. Only you can still move."],"Apocalypse zombie":["Des vagues de zombies arrivent autour de toi, jusqu'à 60 à la fois.","Waves of zombies arrive around you, up to 60 at a time."],"Taille des créatures":["Change la taille de toutes les créatures chargées.","Changes the size of all loaded creatures."],"Détecteur de créatures":["Les créatures à moins de 64 blocs brillent à travers les murs.","Creatures within 64 blocks glow through walls."],"Faire exploser les monstres":["Fait exploser les monstres à moins de 64 blocs, sans abîmer le terrain.","Blows up monsters within 64 blocks without damaging the land."],"Rassembler au bloc visé":["Téléporte les créatures à moins de 64 blocs vers le bloc visé.","Teleports creatures within 64 blocks to the aimed block."],"Lévitation de masse":["Fait s'envoler les créatures à moins de 64 blocs.","Lifts creatures within 64 blocks into the air."],"Enflammer les créatures":["Met le feu aux créatures à moins de 64 blocs.","Sets creatures within 64 blocks on fire."],"Cratère au bloc visé":["Creuse un grand cratère au bloc visé. Impossible à annuler.","Blasts a large crater at the aimed block. Cannot be undone."],"Puissance de la bombe":["Choisis le rayon du cratère : 40, 80 ou 130 blocs.","Pick the crater radius: 40, 80 or 130 blocks."],"Bombe nucléaire au bloc visé":["Explosion géante après 3 secondes. Éloigne-toi. Impossible à annuler.","A giant blast after 3 seconds. Get away. Cannot be undone."],"Tornade au bloc visé":["Une tornade se déplace, arrache des blocs et aspire les créatures.","A moving tornado rips up blocks and pulls in creatures."],"Séisme":["La terre tremble et des crevasses s'ouvrent autour de toi.","The ground shakes and cracks open around you."],"Volcan au bloc visé":["Un volcan sort de terre puis entre en éruption.","A volcano rises from the ground and erupts."],"Météorite géante":["Une météorite s'écrase sur le bloc visé et creuse un cratère.","A meteorite crashes into the aimed block and digs a crater."],"Abri équipé":["Pose un abri en bois avec table de craft, four et coffre.","Places a wooden shelter with a crafting table, furnace and chest."],"Tour de guet":["Pose une tour en pierre de 30 blocs avec une échelle.","Places a 30-block stone tower with a ladder."],"Pyramide":["Pose une pyramide creuse en grès.","Places a hollow sandstone pyramid."],"Arène":["Pose une arène ronde de 20 blocs de rayon.","Places a round arena with a 20-block radius."],"Dôme de verre":["Pose un dôme de verre de 14 blocs de rayon autour de toi.","Places a glass dome with a 14-block radius around you."],"Pont vers le bloc visé":["Construit un pont de ta position jusqu'au bloc visé.","Builds a bridge from where you stand to the aimed block."],"Escalier vers le ciel":["Construit 80 marches droit devant toi.","Builds 80 steps straight ahead of you."],"Puits jusqu'au fond":["Creuse un puits de 3 × 3 presque jusqu'au fond du monde.","Digs a 3 × 3 shaft almost to the bottom of the world."],"Annuler la construction":["Annule le dernier changement, coffres compris.","Undoes the last change, chests included."],"Rétablir la construction":["Refait le changement que tu viens d'annuler.","Redoes the change you just undid."],"Structure":["Choisis une structure de ton dossier.","Pick a structure from your folder."],"Rotation":["Tourne la structure avant de la placer.","Turns the structure before placing it."],"Aperçu au bloc visé":["Montre la structure en fantôme au bloc visé, sans rien poser.","Shows the structure as a ghost at the aimed block, without placing anything."],"Placer au bloc visé":["Pose la structure d'un coup au bloc visé. Tu peux annuler.","Places the whole structure at the aimed block. You can undo it."],"Plan : poser au bloc visé":["Fixe un plan fantôme pour construire toi-même, couche par couche. Rien n'est posé pour toi.","Pins a ghost plan so you can build it yourself, layer by layer. Nothing is placed for you."],"Plan : retirer":["Enlève le plan en cours. Tes blocs restent en place.","Removes the current plan. Your blocks stay in place."],"Annuler":["Annule le dernier changement, coffres compris.","Undoes the last change, chests included."],"Rétablir":["Refait le changement que tu viens d'annuler.","Redoes the change you just undid."],"Capture : coin 1":["Vise un bloc pour marquer le premier coin de la zone.","Aim at a block to mark the first corner of the area."],"Capture : coin 2":["Vise un bloc pour marquer le coin opposé de la zone.","Aim at a block to mark the opposite corner of the area."],"Capture : enregistrer":["Enregistre la zone dans un fichier, contenu des coffres compris.","Saves the area to a file, chest contents included."],"Capture : effacer la sélection":["Efface les deux coins choisis.","Clears the two chosen corners."],"Ouvrir le dossier des structures":["Ouvre le dossier où déposer des fichiers .nbt à importer.","Opens the folder where you drop .nbt files to import."],"Recharger les structures":["Relit le dossier après y avoir ajouté des fichiers.","Reads the folder again after adding files."],"Partager la structure":["Affiche le fichier de la structure, prêt à être envoyé.","Shows the structure's file, ready to send."],"Langue":["Auto suit la langue de Minecraft. Tu peux aussi forcer l'anglais ou le français.","Auto follows Minecraft's language. You can also force English or French."],"Bannière":["Choisis l'image en haut du menu. Les GIF sont animés.","Pick the image at the top of the menu. GIFs are animated."],"Ouvrir le dossier des bannières":["Ouvre le dossier où déposer tes images.","Opens the folder where you drop your images."],"Recharger les bannières":["Relit le dossier après y avoir ajouté des images.","Reads the folder again after adding images."],"Titre sur la bannière":["Écrit Vessel Trainer par-dessus ta bannière.","Writes Vessel Trainer over your banner."],"Nom sur la barre d'objets":["Affiche le nom du trainer à côté de la barre d'objets.","Shows the trainer's name next to the hotbar."],"Menu à droite":["Place le menu à droite de l'écran.","Moves the menu to the right of the screen."],"Profil":["Choisis l'un des 3 profils de cheats.","Pick one of the 3 cheat profiles."],"Enregistrer le profil":["Garde tes cheats actuels dans le profil choisi.","Saves your current cheats in the chosen profile."],"Charger le profil":["Réactive les cheats du profil choisi.","Turns the chosen profile's cheats back on."],"Thème":["Change la couleur du menu.","Changes the menu color."],"Sons du menu":["Active les petits sons de navigation.","Turns the navigation sounds on or off."],"Infos à l'écran":["Affiche les coordonnées, le biome, les FPS et ta vitesse.","Shows coordinates, biome, FPS and your speed."],"Liste des cheats actifs":["Affiche sur le côté les cheats en marche.","Shows the running cheats on the side."],"Zoom (touche C)":["Choisis la force du zoom. Maintiens C pour zoomer.","Pick the zoom strength. Hold C to zoom."],"Descriptions des boutons":["Affiche ou masque ce texte d'aide sous le menu.","Shows or hides this help text under the menu."],"Bibliothèque en ligne":["Parcours les structures du site et télécharge-les sans quitter le jeu.","Browse the website's structures and download them without leaving the game."],"Actualiser la liste":["Récupère la liste des structures du site. Il faut être connecté à internet.","Gets the list of structures from the website. You need to be online."],"Structure en ligne":["Choisis une structure de la bibliothèque, avec le nom de son auteur.","Pick a structure from the library, with its author's name."],"Télécharger la structure":["Ajoute la structure choisie à ton dossier. Elle est ensuite prête à placer.","Adds the chosen structure to your folder, ready to place."],"Favoris":["Tes boutons épinglés. Sur n'importe quel bouton, appuie sur B pour l'ajouter ici.","Your pinned buttons. On any button, press B to add it here."],"Aucun favori":["Sélectionne un bouton et appuie sur B pour l'épingler ici.","Select a button and press B to pin it here."],"Rechercher dans le menu":["Tape quelques lettres pour trouver n'importe quel bouton. Raccourci : N.","Type a few letters to find any button. Shortcut: N."],"Tape pour chercher":["Écris le nom d'un bouton, en français ou en anglais.","Type the name of a button, in English or French."],"Aucun résultat":["Essaie un autre mot.","Try another word."],"Caméra":["Quitte ton personnage pour explorer et filmer ton monde.","Leave your character to explore and film your world."],"Caméra libre":["Vole à travers tout avec tes touches de déplacement. Saut pour monter, Sneak pour descendre. Ton corps reste sur place.","Fly through anything with your movement keys. Jump goes up, Sneak goes down. Your body stays where it is."],"Vitesse de la caméra":["Règle la vitesse de vol de la caméra libre.","Sets how fast the free camera flies."],"Mode cinéma":["Mouvements doux et interface cachée. Ouvre le menu pour la retrouver.","Smooth movement and a hidden interface. Open the menu to bring it back."],"Ajouter un point au trajet":["Enregistre la position et le regard actuels comme étape du trajet.","Saves your current position and view as a step of the path."],"Durée du trajet":["Le temps que met la caméra à parcourir tout le trajet.","How long the camera takes to travel the whole path."],"Lire le trajet":["La caméra suit tes points tout en douceur, pour filmer une scène.","The camera glides through your points to film a scene."],"Effacer le trajet":["Supprime tous les points du trajet.","Removes every point of the path."],"Tsunami":["Une vraie vague d'eau arrive de là où tu regardes et balaie tout sur son passage.","A real wall of water comes from where you look and sweeps everything away."],"Blizzard":["Pendant 40 secondes, la neige recouvre tout, l'eau gèle et les créatures se figent.","For 40 seconds, snow covers everything, water freezes and creatures seize up."],"Tempête de sable":["Pendant 40 secondes, le vent te pousse, la vue se brouille et le sable s'accumule.","For 40 seconds, the wind pushes you, the view blurs and sand piles up."],"Fun":["Des effets absurdes et sans danger pour ton monde. Tout peut être annulé.","Silly effects that are safe for your world. Everything can be undone."],"Roue de la chance":["La roue tourne et choisit un effet surprise pendant 20 secondes.","The wheel spins and picks a surprise effect for 20 seconds."],"Mode roulette":["Un nouvel effet surprise toutes les 30 secondes, jusqu'à ce que tu l'arrêtes.","A new surprise effect every 30 seconds, until you stop it."],"Soirée disco":["Une boule à facettes, des lumières, de la musique et des créatures qui sautent en rythme.","A disco ball, lights, music and creatures jumping to the beat."],"Tête géante":["Ta tête gonfle. Regarde-toi en vue extérieure ou avec la caméra libre.","Your head grows. See it from the outside or with the free camera."],"Pistolet à poulets":["La touche R tire des poulets. Ils disparaissent après 10 secondes.","The R key fires chickens. They vanish after 10 seconds."],"Échange de corps":["Tu échanges ta place avec la créature visée, ou la plus proche.","You swap places with the aimed creature, or the nearest one."],"Tout arrêter":["Coupe tous les effets Fun et retire ce qu'ils ont laissé dans le monde.","Turns every Fun effect off and removes what they left in the world."],"Retirer les portails":["Fait disparaître les deux portails posés avec le pouvoir Portail.","Removes both portals placed with the Portal power."],"Fun : personnage":["Change ton apparence et ta façon de marcher.","Change how you look and how you walk."],"Fun : créatures":["Des effets absurdes pour les créatures autour de toi.","Silly effects for the creatures around you."],"Fun : monde":["Change ce que tu vois et la façon dont le monde réagit.","Change what you see and how the world reacts."],"Fun : sons":["Rends les sons du jeu complètement ridicules.","Make the sounds of the game completely ridiculous."],"Fun : mini-jeux":["Des petits jeux avec un score. Tout ce qu'ils construisent disparaît à la fin.","Small games with a score. Everything they build disappears at the end."],"Fun : objets":["Des objets idiots à utiliser avec la touche R.","Silly items to use with the R key."],"Traînée":["Laisse une traînée de particules derrière toi quand tu bouges.","Leaves a trail of particles behind you as you move."],"Pas sonores":["Chaque pas fait un bruit ridicule.","Every step makes a ridiculous noise."],"Marche disco":["Des dalles colorées s'allument sous tes pieds. Les vrais blocs ne changent pas.","Colored tiles light up under your feet. The real blocks do not change."],"Déguisement":["Tu ressembles à une créature. Regarde-toi avec F5 ou la caméra libre.","You look like a creature. See it with F5 or the free camera."],"Mode fantôme":["Ton corps disparaît, tu flottes en tombant et une aura d'âmes t'entoure.","Your body disappears, you drift down slowly and souls surround you."],"Danse":["Ton personnage danse sans s'arrêter. Regarde-toi avec F5 ou la caméra libre.","Your character dances nonstop. See it with F5 or the free camera."],"Chapeaux":["Les créatures proches reçoivent un chapeau.","Nearby creatures get a hat."],"Parade":["Une file de créatures te suit partout.","A line of creatures follows you everywhere."],"Chorale":["Cinq villageois apparaissent et chantent pour toi, puis repartent.","Five villagers appear, sing for you, then leave."],"Tour de cochons":["Une tour de six cochons au bloc visé, pendant 15 secondes.","A tower of six pigs at the aimed block, for 15 seconds."],"Noms rigolos":["Les créatures proches reçoivent un nom absurde, retiré à la fin.","Nearby creatures get a silly name, removed at the end."],"Moutons arc-en-ciel":["La laine des moutons change de couleur. Elle revient à la normale à la fin.","Sheep wool changes color. It goes back to normal at the end."],"Poulets de combat":["Quatre poulets te suivent et attaquent les monstres.","Four chickens follow you and attack monsters."],"Spectacle de feux d'artifice":["Vingt secondes de fusées colorées autour de toi.","Twenty seconds of colorful rockets around you."],"Mode miroir":["La gauche et la droite sont inversées, au clavier comme à la souris.","Left and right are swapped, on the keyboard and the mouse."],"Filtre d'écran":["Change le rendu : vieux film, néon, noir et blanc ou pixelisé.","Changes the picture: old film, neon, black and white or pixelated."],"Monde penché":["L'écran tangue doucement, comme sur un bateau.","The screen slowly rocks, like on a boat."],"Lune énorme":["La lune remplit le ciel la nuit.","The moon fills the sky at night."],"Blocs rebondissants":["Tu rebondis sur le sol comme sur du slime, sans dégâts.","You bounce on the ground like on slime, without damage."],"Sons échangés":["Chaque créature emprunte la voix d'une autre.","Each creature borrows the voice of another."],"Voix aiguë":["Tous les sons du jeu sont accélérés.","All the sounds of the game are sped up."],"Musique de boîte de nuit":["Un rythme avec des lumières, partout où tu vas.","A beat with lights, everywhere you go."],"Bouton pet":["Aucune utilité. Un bruit, c'est tout.","No use at all. Just a noise."],"Sol de lave":["Sur une plateforme dans le ciel, les blocs tombent derrière toi. Tiens le plus longtemps possible.","On a platform in the sky, blocks vanish behind you. Last as long as you can."],"Chasse au trésor":["Trouve le trésor caché. Le trainer te dit si tu chauffes.","Find the hidden treasure. The trainer tells you if you are getting closer."],"Tir aux poulets":["Élimine un maximum de poulets en 30 secondes.","Take out as many chickens as you can in 30 seconds."],"Parcours instantané":["Un parcours apparaît devant toi. Atteins le bloc d'or.","A parkour appears in front of you. Reach the gold block."],"Survis à la vague":["Des vagues de créatures arrivent. Tu as 5 vies, et tu ne peux pas mourir vraiment.","Waves of creatures arrive. You have 5 lives, and you cannot really die."],"Arrêter le mini-jeu":["Termine le mini-jeu en cours et retire tout ce qu'il a construit.","Ends the current mini-game and removes everything it built."],"Pistolet à confettis":["La touche R tire une explosion de confettis, sans dégâts.","The R key fires a burst of confetti, without damage."],"Canne à pêche magique":["La touche R pêche un objet absurde là où tu vises.","The R key fishes a silly item where you aim."],"Trampoline portable":["La touche R pose un trampoline. Il reste 90 secondes, et 3 au maximum.","The R key places a trampoline. It stays for 90 seconds, 3 at most."],"Recevoir l'épée en plastique":["Une épée qui envoie valser sans blesser personne.","A sword that sends things flying without hurting anyone."],"Admin":["Le panneau des admins d'un serveur : joueurs, modération, monde et événements. Le serveur vérifie chaque action.","The server admin panel: players, moderation, world and events. The server checks every action."],"Joueurs connectés":["Choisis un joueur connecté pour agir sur lui.","Pick an online player to act on them."],"Moi":["Tes outils personnels pour surveiller le serveur.","Your own tools to watch over the server."],"Modération":["Annonces, chat, liste blanche et bannissements.","Announcements, chat, whitelist and bans."],"Joueurs bannis":["Choisis un nom pour le débannir.","Pick a name to unban it."],"Monde du serveur":["Heure, météo, difficulté, règles et nettoyage du monde.","Time, weather, difficulty, rules and cleanup."],"Règles du serveur":["Active ou coupe les règles du monde pour tout le serveur.","Turns world rules on or off for the whole server."],"Événements":["Lance une catastrophe à l'endroit que tu vises ou autour de toi, pour animer le serveur.","Starts a disaster where you aim or around you, to liven up the server."],"Serveur":["Performances, sauvegarde et journal des actions.","Performance, saving and the action log."],"Journal admin":["Les dernières actions des admins. Tout est aussi écrit dans logs/vessel-admin.log.","The latest admin actions. Everything is also written to logs/vessel-admin.log."],"Aller vers ce joueur":["Te téléporte sur ce joueur.","Teleports you to this player."],"Amener ce joueur ici":["Téléporte ce joueur sur toi.","Teleports this player to you."],"Geler":["Bloque ce joueur sur place jusqu'à ce que tu le dégèles.","Holds this player in place until you unfreeze them."],"Rendre muet":["Empêche ce joueur d'écrire dans le chat.","Stops this player from writing in chat."],"Voir l'inventaire":["Affiche une copie de son inventaire. Rien ne peut être déplacé.","Shows a copy of their inventory. Nothing can be moved."],"Voir le coffre de l'Ender":["Affiche une copie de son coffre de l'Ender. Rien ne peut être déplacé.","Shows a copy of their Ender chest. Nothing can be moved."],"Vider l'inventaire":["Supprime tout son inventaire. Appuie deux fois pour confirmer.","Deletes their whole inventory. Press twice to confirm."],"Expulser":["Déconnecte ce joueur. Appuie deux fois pour confirmer.","Disconnects this player. Press twice to confirm."],"Bannir":["Bannit ce joueur du serveur. Appuie deux fois pour confirmer.","Bans this player from the server. Press twice to confirm."],"Donner les droits d'op":["Réservé au propriétaire. Appuie deux fois pour confirmer.","Owner only. Press twice to confirm."],"Retirer les droits d'op":["Réservé au propriétaire. Appuie deux fois pour confirmer.","Owner only. Press twice to confirm."],"Invincible (admin)":["Tu ne prends plus de dégâts sur le serveur.","You take no damage on the server."],"Vol (admin)":["Tu peux voler sur le serveur.","You can fly on the server."],"Faire une annonce":["Envoie un message à tous les joueurs.","Sends a message to every player."],"Couper le chat":["Seuls les admins peuvent encore écrire.","Only admins can still write."],"Liste blanche":["Seuls les joueurs de la liste blanche peuvent rejoindre.","Only whitelisted players can join."],"Mettre le jour":["Passe le serveur au matin.","Sets the server to morning."],"Mettre la nuit":["Passe le serveur à la nuit.","Sets the server to night."],"Ciel dégagé":["Arrête la pluie et les orages.","Stops rain and storms."],"Faire pleuvoir":["Lance la pluie sur le serveur.","Starts rain on the server."],"Lancer un orage":["Lance un orage sur le serveur.","Starts a thunderstorm on the server."],"Difficulté : paisible":["Change la difficulté du serveur.","Changes the server difficulty."],"Difficulté : facile":["Change la difficulté du serveur.","Changes the server difficulty."],"Difficulté : normale":["Change la difficulté du serveur.","Changes the server difficulty."],"Difficulté : difficile":["Change la difficulté du serveur.","Changes the server difficulty."],"Combat entre joueurs":["Les joueurs peuvent se blesser entre eux.","Players can hurt each other."],"Garder l'inventaire à la mort":["Les joueurs gardent leurs objets en mourant.","Players keep their items when they die."],"Dégâts des créatures au décor":["Les creepers et autres créatures peuvent abîmer le décor.","Creepers and other mobs can damage the world."],"Apparition des monstres hostiles":["Les monstres apparaissent normalement.","Monsters spawn normally."],"Apparition des phantoms":["Les phantoms apparaissent la nuit.","Phantoms spawn at night."],"Dégâts de chute":["Les chutes blessent les joueurs.","Falls hurt players."],"Dégâts de feu":["Le feu blesse les joueurs.","Fire hurts players."],"Le temps passe":["Le cycle du jour et de la nuit avance.","The day and night cycle moves on."],"La météo change":["La météo change toute seule.","The weather changes by itself."],"Retirer les objets au sol":["Supprime les objets posés au sol. Appuie deux fois pour confirmer.","Removes items on the ground. Press twice to confirm."],"Lancer une tornade":["Là où tu vises. Appuie deux fois pour confirmer.","Where you aim. Press twice to confirm."],"Lancer un séisme":["Autour de toi. Appuie deux fois pour confirmer.","Around you. Press twice to confirm."],"Lancer un volcan":["Là où tu vises. Appuie deux fois pour confirmer.","Where you aim. Press twice to confirm."],"Lancer une météorite":["Là où tu vises. Appuie deux fois pour confirmer.","Where you aim. Press twice to confirm."],"Lancer un tsunami":["Vient de la direction où tu regardes. Appuie deux fois pour confirmer.","Comes from where you look. Press twice to confirm."],"Lancer un blizzard":["Te suit et couvre le sol de neige. Appuie deux fois pour confirmer.","Follows you and covers the ground in snow. Press twice to confirm."],"Lancer une tempête de sable":["Te suit et couvre le sol de sable. Appuie deux fois pour confirmer.","Follows you and covers the ground in sand. Press twice to confirm."],"Lancer la bombe":["Là où tu vises, après un compte à rebours. Appuie deux fois pour confirmer.","Where you aim, after a countdown. Press twice to confirm."],"Sauvegarder le monde":["Enregistre le monde tout de suite.","Saves the world right now."],"Arrêter le serveur":["Réservé au propriétaire. Appuie deux fois pour confirmer.","Owner only. Press twice to confirm."],"Soigner ce joueur":["Rend toute sa vie à ce joueur et éteint le feu.","Restores this player's health and puts out fire."],"Nourrir ce joueur":["Remplit la barre de faim de ce joueur.","Fills this player's hunger bar."],"Mode de jeu du joueur":["Change le mode de jeu de ce joueur.","Changes this player's game mode."],"Mode observateur":["Te passe en spectateur pour observer sans être vu, puis te rend ton mode.","Switches you to spectator to watch unseen, then gives your mode back."],"Retirer les monstres du serveur":["Supprime les monstres hostiles chargés, sauf le dragon de l'Ender. Appuie deux fois pour confirmer.","Removes loaded hostile mobs, except the Ender Dragon. Press twice to confirm."],"Kits d'objets":["Enregistre ton inventaire pour le retrouver en un clic, dans n'importe quel monde.","Saves your inventory so you can get it back in one click, in any world."],"Kit":["Choisis un des 3 emplacements.","Pick one of the 3 slots."],"Enregistrer mon inventaire":["Enregistre tout ton inventaire dans ce kit.","Saves your whole inventory in this kit."],"Reprendre ce kit":["Remplace ton inventaire par ce kit. Appuie deux fois pour confirmer.","Replaces your inventory with this kit. Press twice to confirm."],"Ralenti":["Ralentit le monde à un quart de sa vitesse, pour admirer une explosion.","Slows the world to a quarter of its speed, to watch an explosion."],"Copier le code du profil":["Copie un code à envoyer à un ami. Il ne contient que tes réglages de cheats.","Copies a code to send to a friend. It only holds your cheat settings."],"Coller un code de profil":["Colle le code reçu dans cet emplacement. Charge ensuite le profil pour l'appliquer.","Pastes a received code into this slot. Then load the profile to apply it."],"Créateur de thème":["Choisis tes propres couleurs de menu. Le changement se voit tout de suite.","Pick your own menu colors. You see the change right away."],"Teinte":["La couleur principale du menu.","The main color of the menu."],"Luminosité":["La force de la couleur.","How strong the color is."],"Dégradé":["Le fondu de la couleur dans l'en-tête.","How the color fades in the header."],"Pinceau de construction":["Peins, remplace et sculpte le décor à distance avec la touche R.","Paint, replace and sculpt the world from a distance with the R key."],"Activer le pinceau (touche R)":["Fait du pinceau ton pouvoir actuel. Maintiens R en visant.","Makes the brush your current power. Hold R while aiming."],"Mode du pinceau":["Peindre et Remplacer utilisent le bloc que tu tiens. Élever, Creuser et Lisser sculptent le terrain.","Paint and Replace use the block you hold. Raise, Dig and Smooth sculpt the terrain."],"Taille du pinceau":["Le rayon du pinceau, en blocs.","The radius of the brush, in blocks."],"Annuler le dernier trait":["Annule tout le dernier trait de pinceau.","Undoes the whole last brush stroke."],"Créateur de créatures":["Choisis la taille, la vie et l'équipement avant de créer ta créature.","Pick a size, health and gear before creating your creature."],"Créature":["La créature à créer.","The creature to create."],"Taille de la créature":["De minuscule à géante.","From tiny to giant."],"Vie de la créature":["Multiplie sa vie.","Multiplies its health."],"Équipement":["Son armure et son épée. Seules les créatures humanoïdes les montrent.","Its armor and sword. Only humanoid creatures show them."],"Créer la créature":["La fait apparaître là où tu vises.","Spawns it where you aim."],"Bibliothèque de bannières":["Les bannières partagées sur le site, à télécharger depuis le jeu.","The banners shared on the website, to download from the game."],"Actualiser les bannières":["Se connecte au site pour lire la liste. Rien n'est envoyé.","Connects to the website to read the list. Nothing is sent."],"Bannière en ligne":["Choisis une bannière de la liste.","Pick a banner from the list."],"Télécharger et utiliser":["Télécharge cette bannière et l'utilise tout de suite.","Downloads this banner and uses it right away."],"Manette":["Start ouvre le menu, la croix ou le stick navigue, A valide, B revient, Y met en favori.","Start opens the menu, the D-pad or stick navigates, A selects, B goes back, Y adds a favorite."],"X-ray":["Vois les minerais à travers le sol. Seulement en solo.","See ores through the ground. Singleplayer only."],"Activer le X-ray":["Cache tous les blocs sauf ceux choisis, et éclaire les galeries.","Hides every block except the chosen ones, and lights up the caves."],"Blocs visibles":["Les minerais seuls, ou aussi les coffres, générateurs et autres trésors.","Ores only, or chests, spawners and other treasures too."],"Aimbot":["Vise tout seul la créature la plus proche de ton viseur. Seulement en solo.","Aims by itself at the creature closest to your crosshair. Singleplayer only."],"Activer l'aimbot":["Tourne ta vue vers la cible tant qu'elle est devant toi et visible.","Turns your view toward the target while it is in front of you and in sight."],"Cibles":["Les créatures que l'aimbot vise. Les joueurs ne sont jamais visés.","The creatures the aimbot aims at. Players are never targeted."],"Portée de visée":["La distance maximale de la cible, en blocs.","How far the target can be, in blocks."],"Vitesse de visée":["À quelle vitesse ta vue se tourne vers la cible.","How fast your view turns toward the target."],"Mini-carte":["Une carte des alentours en haut de l'écran, le nord en haut. Seulement en solo.","A map of the area at the top of the screen, north up. Singleplayer only."],"Taille de la mini-carte":["La taille de la carte à l'écran.","The size of the map on screen."],"Minerai":["Montre tous les minerais, ou un seul. Les autres sont cachés avec le reste.","Shows every ore, or just one. The others are hidden with the rest."],"Remettre le menu à sa place":["Ramène le menu dans son coin après l'avoir déplacé avec Alt.","Brings the menu back to its corner after moving it with Alt."],"Écran d'accueil Vessel":["Le logo VESSELCRAFT, Vess, ses phrases jaunes et le bouton Vessel Trainer sur l'écran d'accueil du jeu.","The VESSELCRAFT logo, Vess, its yellow lines and the Vessel Trainer button on the game's title screen."],"Vérifier les mises à jour":["Au lancement, demande au site si une nouvelle version est sortie et l'affiche sur l'écran d'accueil.","At launch, asks the website whether a new version is out and shows it on the title screen."]};
const describe = (label, menu) => { const text = DESCRIPTIONS[label] || DESCRIPTIONS['@' + menu]; return text ? text[lang === 'fr' ? 0 : 1] : ''; };
